import sys

def main():
    # Read all input from standard input at once
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    # Read N and D
    try:
        n_str = next(iterator)
        d_str = next(iterator)
        N = int(n_str)
        D = int(d_str)
    except StopIteration:
        return

    # Read the N snakes' data (T_i, L_i)
    snakes = []
    for _ in range(N):
        try:
            t = int(next(iterator))
            l = int(next(iterator))
            snakes.append((t, l))
        except StopIteration:
            break

    # For each k from 1 to D, find the maximum weight
    for k in range(1, D + 1):
        max_weight = 0
        for t, l in snakes:
            # The new length is L_i + k
            # The weight is T_i * (L_i + k)
            weight = t * (l + k)
            if weight > max_weight:
                max_weight = weight
        print(max_weight)

if __name__ == '__main__':
    main()
